const now=new Date("2026-01-02T00:00:00Z"), s=now/1000;
const m=(type,o,t)=>({type,contact:{optedIn:o,lastInboundTimestamp:t}});
const c=[["text in window",m("text",true,String(s-3600))],["text 24h+1",m("text",true,String(s-86401))],["text 23h59",m("text",true,String(s-86399))],["text never",m("text",true,null)],["text ms ts",m("text",true,String(s*1000-3600000))],["text no optin",m("text",false,String(s-10))],["tpl never",m("template",true,null)],["tpl old",m("template",true,String(s-999999))],["tpl no optin",m("template",false,null)],["bad type",m("image",true,null)],["garbage",m("text",true,"abc")]];
for(const [n,x] of c) console.log(n,JSON.stringify(d(x,now)));'

